"""gitignore-style pattern matching. See task.md."""

from __future__ import annotations

import re

_STAR_STAR = object()

_CLASS_SPECIAL = set("]\\^-")


class PatternError(ValueError):
    """Raised for a malformed character class or a dangling escape."""


def _strip_trailing_spaces(line: str) -> str:
    while line.endswith(" "):
        j = len(line) - 1
        k = j - 1
        backslashes = 0
        while k >= 0 and line[k] == "\\":
            backslashes += 1
            k -= 1
        if backslashes % 2 == 1:
            break
        line = line[:j]
    return line


def _escape_in_class(ch: str) -> str:
    if ch in _CLASS_SPECIAL:
        return "\\" + ch
    return ch


def _tokenize_class_body(text: str, k: int, n: int):
    """Return (atoms, index_of_closing_bracket)."""
    atoms = []
    first = True
    while k < n:
        ch = text[k]
        if ch == "]" and not first:
            return atoms, k
        if ch == "]" and first:
            atoms.append(("]", False))
            k += 1
            first = False
            continue
        if ch == "\\":
            if k + 1 >= n:
                raise PatternError("dangling escape in character class")
            atoms.append((text[k + 1], True))
            k += 2
            first = False
            continue
        atoms.append((ch, False))
        k += 1
        first = False
    raise PatternError("unterminated character class")


def _build_class_items(atoms):
    items = []
    i = 0
    n = len(atoms)
    while i < n:
        ch, escaped = atoms[i]
        if i + 1 < n and atoms[i + 1] == ("-", False) and (i + 1) != n - 1:
            end_ch, _ = atoms[i + 2]
            if ord(end_ch) < ord(ch):
                raise PatternError("character range end below start")
            items.append(("range", ch, end_ch))
            i += 3
            continue
        items.append(("char", ch))
        i += 1
    return items


def _compile_segment(text: str):
    """Compile a single path segment (no '/') into a regex Pattern."""
    out = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c == "\\":
            if i + 1 >= n:
                raise PatternError("dangling escape")
            out.append(re.escape(text[i + 1]))
            i += 2
        elif c == "*":
            while i < n and text[i] == "*":
                i += 1
            out.append("[^/]*")
        elif c == "?":
            out.append("[^/]")
            i += 1
        elif c == "[":
            j = i + 1
            negate = False
            if j < n and text[j] == "!":
                negate = True
                j += 1
            atoms, close_idx = _tokenize_class_body(text, j, n)
            items = _build_class_items(atoms)
            parts = []
            for item in items:
                if item[0] == "range":
                    _, a, b = item
                    parts.append(_escape_in_class(a) + "-" + _escape_in_class(b))
                else:
                    _, ch = item
                    parts.append(_escape_in_class(ch))
            cls = "".join(parts)
            out.append("[" + ("^" if negate else "") + cls + "]")
            i = close_idx + 1
        else:
            out.append(re.escape(c))
            i += 1
    return re.compile("".join(out))


def _compile_line(line: str):
    text = _strip_trailing_spaces(line)
    if text == "":
        return None
    if text.startswith("#"):
        return None

    negate = False
    if text.startswith("!"):
        negate = True
        text = text[1:]

    dir_only = False
    if text.endswith("/"):
        dir_only = True
        text = text[:-1]

    if text == "":
        return None

    anchored = "/" in text
    if text.startswith("/"):
        text = text[1:]

    seg_texts = text.split("/")
    seg_specs = []
    for seg_text in seg_texts:
        if anchored and seg_text == "**":
            seg_specs.append(_STAR_STAR)
        else:
            seg_specs.append(_compile_segment(seg_text))

    return (negate, dir_only, anchored, seg_specs)


def _matches_anchored(seg_specs, path_segments) -> bool:
    n = len(seg_specs)
    m = len(path_segments)

    def rec(pi, si):
        if pi == n:
            return si == m
        spec = seg_specs[pi]
        if spec is _STAR_STAR:
            if pi == n - 1 and pi > 0:
                return si < m
            for k in range(si, m + 1):
                if rec(pi + 1, k):
                    return True
            return False
        if si >= m:
            return False
        if spec.fullmatch(path_segments[si]) is None:
            return False
        return rec(pi + 1, si + 1)

    return rec(0, 0)


def _matches_basename(seg_specs, path_segments) -> bool:
    spec = seg_specs[0]
    return spec.fullmatch(path_segments[-1]) is not None


def is_ignored(patterns: list[str], path: str, is_dir: bool) -> bool:
    """Return True when `path` is ignored by `patterns`."""
    compiled = [c for c in (_compile_line(line) for line in patterns) if c is not None]

    path_segments = path.split("/")
    result = False
    for negate, dir_only, anchored, seg_specs in compiled:
        if dir_only and not is_dir:
            continue
        if anchored:
            matched = _matches_anchored(seg_specs, path_segments)
        else:
            matched = _matches_basename(seg_specs, path_segments)
        if matched:
            result = not negate
    return result
